func (q *Queries) ListSubscriptions(ctx context.Context, dollar_1 string) ([]ListSubscriptionsRow, error) {
	rows, err := q.db.Query(ctx, listSubscriptions, dollar_1)
	if err != nil {
		return nil, err
	}
	defer rows.Close()
	var items []ListSubscriptionsRow
	for rows.Next() {
		var i ListSubscriptionsRow
		if err := rows.Scan(
			&i.ID,
			&i.TenantID,
			&i.PlanSlug,
			&i.State,
			&i.BillingTerm,
			&i.TrialEndsAt,
			&i.CurrentPeriodEnd,
			&i.GraceEndsAt,
			&i.CancelledAt,
			&i.CreatedAt,
			&i.TenantName,
			&i.TenantSlug,
		); err != nil {
			return nil, err
		}
		items = append(items, i)
	}
	if err := rows.Err(); err != nil {
		return nil, err
	}
	return items, nil
}

const listTenants = `-- name: ListTenants :many
SELECT t.id, t.name, t.slug, t.billing_email, t.edition, t.status, t.owner_org_id, t.created_at, s.plan_slug, s.state AS subscription_state,
       (SELECT count(*) FROM organizations o WHERE o.tenant_id = t.id AND o.deleted_at IS NULL) AS org_count
FROM tenants t
LEFT JOIN LATERAL (
  SELECT sub.plan_slug, sub.state FROM subscriptions sub
  WHERE sub.tenant_id = t.id AND sub.state <> 'cancelled'
  ORDER BY sub.created_at DESC LIMIT 1
) s ON true
WHERE ($1::text = '' OR t.status = $1)
ORDER BY t.created_at DESC LIMIT 200
`

type ListTenantsRow struct {
	ID                pgtype.UUID        `json:"id"`
	Name              string             `json:"name"`
	Slug              string             `json:"slug"`
	BillingEmail      string             `json:"billing_email"`
	Edition           string             `json:"edition"`
	Status            string             `json:"status"`
	OwnerOrgID        pgtype.UUID        `json:"owner_org_id"`
	CreatedAt         pgtype.Timestamptz `json:"created_at"`
	PlanSlug          string             `json:"plan_slug"`
	SubscriptionState string             `json:"subscription_state"`
	OrgCount          int64              `json:"org_count"`
}

// ---------- tenants ----------
// LATERAL pins the newest live subscription — a tenant with multiple
// non-cancelled subs must not double-row the listing.
func (q *Queries) ListTenants(ctx context.Context, dollar_1 string) ([]ListTenantsRow, error) {
	rows, err := q.db.Query(ctx, listTenants, dollar_1)
	if err != nil {
		return nil, err
	}
	defer rows.Close()
	var items []ListTenantsRow
	for rows.Next() {
		var i ListTenantsRow
		if err := rows.Scan(
			&i.ID,
			&i.Name,
			&i.Slug,
			&i.BillingEmail,
			&i.Edition,
			&i.Status,
			&i.OwnerOrgID,
			&i.CreatedAt,
			&i.PlanSlug,
			&i.SubscriptionState,
			&i.OrgCount,
		); err != nil {
			return nil, err
		}
		items = append(items, i)
	}
	if err := rows.Err(); err != nil {
		return nil, err
	}
	return items, nil
}

